@st.cache_data(show_spinner=False)
def read_sensor_csv(file_or_path):
    df = pd.read_csv(file_or_path)
    needed = {'Time', 'Pass/Fail'}
    if not needed.issubset(df.columns):
        raise ValueError('CSV harus memuat kolom Time dan Pass/Fail, sesuai dataset asli.')
    if not df['Pass/Fail'].isin([-1, 1]).all():
        raise ValueError('Label harus menggunakan Pass = -1 dan Fail = 1.')
    ts = pd.to_datetime(df['Time'], errors='coerce', format='%Y-%m-%d %H:%M:%S')
    if ts.isna().any():
        raise ValueError('Format kolom Time tidak cocok: seharusnya YYYY-MM-DD HH:MM:SS.')
    swap = ts.dt.day <= 12
    corrected = ts.copy()
    corrected.loc[swap] = pd.to_datetime(dict(
        year=ts.loc[swap].dt.year, month=ts.loc[swap].dt.day,
        day=ts.loc[swap].dt.month, hour=ts.loc[swap].dt.hour,
        minute=ts.loc[swap].dt.minute, second=ts.loc[swap].dt.second
    ))
    df['Time'] = corrected
    return df, df.drop(columns=['Time', 'Pass/Fail']), int(swap.sum())

SOURCE_CANDIDATES = [ROOT / 'data' / 'data.csv', ROOT / 'data' / 'data_.csv',
                     ROOT / 'data_.csv', ROOT / 'data.csv', ROOT / 'data_ (3).csv']
SOURCE_CSV = next((p for p in SOURCE_CANDIDATES if p.is_file()), None)

# Data dibaca hanya ketika diperlukan. Isi ringkasan penelitian tidak bergantung CSV.
def get_data():
    source = st.session_state.get('secom_uploaded') or SOURCE_CSV
    if source is None:
        return None, None, None
    try:
        if hasattr(source, 'seek'):
            source.seek(0)
        return read_sensor_csv(source)
    except Exception as exc:
        st.warning(f'Dataset sensor belum bisa dibaca: {exc}')
        return None, None, None


def header(kicker, title, desc):
    st.markdown(f'<div class="hero"><span style="color:#A9D5F4;font-size:.72rem;font-weight:800;letter-spacing:.12em">{escape(kicker)}</span>'
                f'<h1>{escape(title)}</h1><p>{escape(desc)}</p></div>', unsafe_allow_html=True)


def note(text):
    st.markdown(f'<div class="smallblock">{text}</div>', unsafe_allow_html=True)


def chart_layout(fig, height=360):
    fig.update_layout(height=height, paper_bgcolor='rgba(0,0,0,0)',
                      plot_bgcolor='rgba(0,0,0,0)', margin=dict(l=12, r=16, t=35, b=15),
                      font=dict(family='Arial', color=NAVY), legend=dict(orientation='h', y=-.25))
    return fig


def display_table(df, title=None, info=None, filename=None):
    if title:
        st.markdown(f'**{title}**')
    if info:
        st.caption(info)
    st.dataframe(df, hide_index=True, use_container_width=True)
    if filename:
        st.download_button('⬇ Unduh CSV tabel ini', df.to_csv(index=False).encode('utf-8-sig'),
                           file_name=filename, mime='text/csv', key='dl_' + filename)


def chart_bar(df, x, y, color=None, horizontal=False, height=340, caption=None):
    fig = px.bar(df, x=(y if horizontal else x), y=(x if horizontal else y),
                 color=color, orientation='h' if horizontal else 'v',
                 text=(y if horizontal else y), color_discrete_sequence=[BLUE, TEAL, ORANGE])
    fig.update_traces(texttemplate='%{text:.3f}', textposition='outside', cliponaxis=False)
    chart_layout(fig, height)
    st.plotly_chart(fig, use_container_width=True)
    if caption:
        st.caption(caption)


def model_chart(frame, metric_key, n=12):
    f = frame.copy()
    if metric_key not in f.columns:
        return
    if 'Model/Indikator' not in f:
        f=f.rename(columns={f.columns[0]:'Model/Indikator'})
    f['_nilai'] = f[metric_key].astype(str).str.extract(r'([-+]?\d*\.?\d+)')[0].astype(float)
    f = f.dropna(subset=['_nilai']).sort_values('_nilai',ascending=False).head(n)
    chart_bar(f.iloc[::-1], 'Model/Indikator', '_nilai', horizontal=True,
              height=max(350, int(33*len(f)+100)))

