def original_table(k, title):
    if k not in TABLES:
        st.info(f'Output {k} belum tersedia. Dashboard tidak akan mengganti angka dengan data sintetis.')
        return
    source=(f'Output notebook asli · indeks sel {NOTEBOOK_TABLE_SOURCE[k]} (mulai dari 0)' if k in NOTEBOOK_TABLE_SOURCE
            else 'Output Colab Bagian 29–31 yang diberikan pengguna')
    display_table(TABLES[k],title,source + ' · angka tidak dihitung ulang di dashboard',
                  f'SECOM_Bagian_{TABLE_TO_STAGE.get(k,0):02d}_{k}.csv')


def confusion_figure(tp,fn,fp,tn,title):
    z=[[tn,fp],[fn,tp]]
    fig=go.Figure(go.Heatmap(z=z,x=['Prediksi Pass','Prediksi Fail'],
                              y=['Aktual Pass','Aktual Fail'],text=z,
                              texttemplate='%{text}',textfont={'size':18},
                              colorscale=[[0,'#EDF5FB'],[1,'#397DCE']],showscale=False))
    chart_layout(fig,310)
    fig.update_layout(title=title,yaxis=dict(autorange='reversed'))
    st.plotly_chart(fig,use_container_width=True)


def stage_custom_charts(n):
    if n in [2,4,7]:
        a,b,c=st.columns(3)
        a.metric('Jumlah wafer', '1.567')
        b.metric('Pass', '1.463')
        c.metric('Fail', '104')
        fig=px.bar(pd.DataFrame({'Kelas':['Pass','Fail'],'Jumlah':[1463,104]}),
                   x='Kelas',y='Jumlah',color='Kelas',text='Jumlah',
                   color_discrete_map={'Pass':BLUE,'Fail':ORANGE})
        chart_layout(fig,295)
        fig.update_layout(showlegend=False)
        st.plotly_chart(fig,use_container_width=True)
    elif n==3:
        df,sensors,_=get_data()
        if df is not None:
            x=sensors.isna().mean().sort_values(ascending=False).head(20)
            f=pd.DataFrame({'Sensor':x.index.astype(str),'Persentase missing':x.values*100})
            chart_bar(f.iloc[::-1],'Sensor','Persentase missing',horizontal=True,height=490)
            st.caption('Dihitung dari CSV asli yang tersedia, bukan dari skor model.')
        else:
            st.info('Untuk melihat grafik 20 sensor dengan missing tertinggi, unggah CSV SECOM asli di menu “Sumber & Data”. Ringkasan kualitas data tetap tersedia di tabel berikut.')
    elif n==5:
        df,sensors,_=get_data()
        if df is not None:
            monthly=df.assign(Bulan=df['Time'].dt.to_period('M').astype(str),Fail=(df['Pass/Fail']==1).astype(int)).groupby('Bulan',as_index=False).agg(Total=('Fail','size'),Fail=('Fail','sum'))
            monthly['Fail rate (%)']=monthly['Fail']/monthly['Total']*100
            fig=px.line(monthly,x='Bulan',y='Fail rate (%)',markers=True,color_discrete_sequence=[TEAL])
            chart_layout(fig,315)
            st.plotly_chart(fig,use_container_width=True)
            with st.expander('Eksplorasi sensor interaktif (CSV asli)',expanded=False):
                name=st.selectbox('Pilih fitur sensor',sensors.columns.tolist())
                d=pd.DataFrame({'Nilai sensor':pd.to_numeric(df[name],errors='coerce'),
                                'Status':df['Pass/Fail'].map({-1:'Pass',1:'Fail'})}).dropna()
                if not d.empty:
                    fig=px.histogram(d,x='Nilai sensor',color='Status',barmode='overlay',opacity=.62,nbins=45,
                                     color_discrete_map={'Pass':BLUE,'Fail':ORANGE})
                    chart_layout(fig,335)
                    st.plotly_chart(fig,use_container_width=True)
        else:
            st.info('Grafik fail rate bulanan dan eksplorasi sensor akan muncul setelah CSV asli dimuat di menu “Sumber & Data”.')
    elif n==8:
        model_chart(TABLES['screening'],'pr_auc',12)
    elif n==15:
        df=TABLES.get('test_operasi')
        if df is not None and 'Model/Indikator' in df:
            subset=df[df['Model/Indikator'].astype(str).str.contains('UTAMA',case=False)]
            if len(subset):
                row=subset.iloc[0]
                confusion_figure(int(row['TP']),int(row['FN']),int(row['FP']),int(row['TN']),'Extra Trees awal · test acak')
    elif n in [22,23,24,25,26,27]:
        lookup={22:('svm_test',['ROC-AUC','PR-AUC'],'Model'),
                23:('alternatif_cv',['ROC-AUC CV mean'],'Model'),
                24:('eksperimen_24_test',['ROC-AUC Test','PR-AUC Test'],'Model'),
                25:('hasil_25',['ROC-AUC Test','PR-AUC Test'],'Model'),
                26:('ringkasan_26',['ROC-AUC mean','PR-AUC mean'],'Model'),
                27:('hasil_27',['ROC-AUC','PR-AUC'],'Model')}
        k,m,id_col=lookup[n]
        if k in TABLES:
            df=TABLES[k]
            cols=[c for c in m if c in df]
            if id_col in df and cols:
                df=df.melt(id_vars=id_col,value_vars=cols,var_name='Metrik',value_name='Nilai')
                df['Nilai']=pd.to_numeric(df['Nilai'],errors='coerce')
                fig=px.bar(df,x='Metrik',y='Nilai',color=id_col,barmode='group',text='Nilai',
                           color_discrete_sequence=px.colors.qualitative.Safe)
                chart_layout(fig,365)
                fig.update_traces(texttemplate='%{text:.3f}',textposition='outside')
                st.plotly_chart(fig,use_container_width=True)
    elif n==28:
        df=TABLES['bootstrap_28'];fig=go.Figure()
        for _,r in df.iterrows():
            lo,hi,val=float(r['CI 95% bawah']),float(r['CI 95% atas']),float(r['Selisih'])
            label=str(r['Metrik'])
            fig.add_trace(go.Scatter(x=[lo,hi],y=[label,label],mode='lines',line=dict(color=BLUE,width=7),showlegend=False))
            fig.add_trace(go.Scatter(x=[val],y=[label],mode='markers+text',marker=dict(color=TEAL,size=11),
                                     text=[f'{val:+.4f}'],textposition='top center',showlegend=False))
        fig.add_vline(x=0,line_dash='dash',line_color='#A85A68')
        chart_layout(fig,280)
        fig.update_layout(xaxis_title='Selisih model pengembangan − Extra Trees awal')
        st.plotly_chart(fig,use_container_width=True)
    elif n==29:
        cols=st.columns(3)
        cols[0].metric('Fail terdeteksi', '23/26', '+3 vs Blending lama')
        cols[1].metric('Fail terlewat','3','−3')
        cols[2].metric('Alarm palsu','160','+88')
        scenario=st.selectbox('Confusion matrix: pilih skenario historis',TEST_29['Skenario'].tolist(),key='cm29')
        r=TEST_29[TEST_29['Skenario']==scenario].iloc[0]
        confusion_figure(r['TP'],r['FN'],r['FP'],r['TN'],scenario)
        st.caption('ROC-AUC dan PR-AUC tidak berubah akibat penggantian threshold saja. Pemilihan threshold didasarkan pada training OOF.')
    elif n==30:
        show_cost_explorer()
        st.subheader('Ketidakpastian recall pada OOB bootstrap')
        fig=px.bar(BOOTSTRAP_30,x='Strategi',y='Proporsi OOB recall >=81%',text='Proporsi OOB recall >=81%',
                   color='Strategi',color_discrete_sequence=[BLUE,TEAL])
        chart_layout(fig,310)
        fig.update_traces(texttemplate='%{text:.1%}',textposition='outside')
        fig.update_yaxes(range=[0,1.05],tickformat='.0%')
        st.plotly_chart(fig,use_container_width=True)
    elif n==31:
        df=OUTER_31[OUTER_31['Aturan threshold']=='Target Recall >=81%']
        metric=st.selectbox('Pilih metrik outer CV',['ROC-AUC mean','PR-AUC mean','Recall Fail mean','Precision Fail mean','FP per 1000 mean','Biaya/1000 mean (30:1)'],key='metric31')
        chart_bar(df,'Model',metric,height=330,
                  caption='Angka adalah rata-rata outer fold pada training lama; bukan hasil test acak atau test kronologis.')
        st.caption('Strategi target recall: 9 dari 10 fold Blending tetap memenuhi target ≥81%, versus 8 dari 10 untuk Extra Trees.')


def show_cost_explorer():
    st.markdown('#### Simulasi biaya pada hasil test yang **sudah ada**')
    st.write('Ubah rasio biaya untuk melihat konsekuensi tiga skenario klasifikasi historis. Ini bukan optimasi threshold baru dan tidak digunakan untuk memilih model final.')
    ratio=st.slider('Biaya satu FN dibanding biaya satu FP',min_value=1,max_value=100,value=30,step=1,key='ratio_cost')
    df=TEST_29[['Skenario','TP','FN','FP']].copy()
    df['Biaya hipotetis']=df['FN']*ratio+df['FP']
    chart_bar(df,'Skenario','Biaya hipotetis',height=320)
    display_table(df,'Rincian biaya relatif pada test historis',f'Biaya FP = 1; biaya FN = {ratio}. Hasil deskriptif test yang telah digunakan sebelumnya.')
    st.caption('Batas impas Blending threshold lama vs baru = 88/3 ≈ 29,33 : 1. Rasio ini berasal dari test historis, bukan biaya produksi nyata.')


def stage_screen(n, category):
    d=STAGES[n]
    header(f'GOOGLE COLAB / BAGIAN {n:02d} / {category.upper()}',d['title'],
           f'Tahap {n} dari 31 · {d["phase"]} · {d["source"]}')
    st.markdown(f'<div class="stagechips">Bagian {n} — {escape(d["phase"])} · data hasil eksperimen yang sudah tercatat</div>',unsafe_allow_html=True)
    st.progress(n/31,text=f'Alur penelitian: Bagian {n} dari 31')
    st.markdown('### 1. Tujuan tahap ini')
    st.write(d['purpose'])
    st.markdown('### 2. Metode yang digunakan')
    st.write(d['method'])
    st.markdown('### 3. Hasil dan grafik')
    st.info(d['finding'])
    stage_custom_charts(n)
    for k,title in d['tables']:
        with st.expander(f'📊 {title} · klik untuk melihat tabel',expanded=n in {15,21,25,29,30,31}):
            original_table(k,title)
    if d['figures']:
        with st.expander('🖼️ Lihat gambar asli dari output Google Colab', expanded=False):
            for fig_name in d['figures']:
                encoded=ARCHIVED_FIGURES.get(fig_name)
                if encoded:
                    st.image(base64.b64decode(encoded),caption=f'Output asli Google Colab — {fig_name}',use_container_width=True)
    st.markdown('### 4. Penjelasan dan interpretasi')
    st.markdown(f'<div class="story">{escape(d["story"])}</div>',unsafe_allow_html=True)
    if n<31:
        following=STAGES[n+1]
        st.markdown(f'<div class="stepnext"><b>Selanjutnya: Bagian {n+1} — {escape(following["title"])}</b><div>{escape(following["purpose"])}</div></div>',unsafe_allow_html=True)
    else:
        st.success('Eksperimen sampai Bagian 31 telah tercatat. Kesimpulan ilmiah tetap harus mempertimbangkan ketidakpastian hasil dan evaluasi yang tidak sepenuhnya independen.')
    st.caption('Tidak ada training, prediksi ulang, atau optimasi threshold terhadap test dalam dashboard ini.')


def step_picker(ids,key):
    sel=st.selectbox('Pilih tahapan penelitian',ids,key=key,
                     format_func=lambda i:f'Bagian {i:02d} — {STAGES[i]["title"]}')
    i=ids.index(sel)
    left,mid,right=st.columns([1,2,1])
    with left:
        st.button('← Sebelumnya',disabled=i==0,use_container_width=True,key=f'prev_{key}',
                  on_click=lambda: st.session_state.update({key:ids[max(0,ids.index(st.session_state[key])-1)]}))
    with mid:
        st.caption('Gunakan tombol untuk mengikuti urutan penelitian secara bertahap.')
    with right:
        st.button('Berikutnya →',disabled=i==len(ids)-1,use_container_width=True,key=f'next_{key}',
                  on_click=lambda:st.session_state.update({key:ids[min(len(ids)-1,ids.index(st.session_state[key])+1)]}))
    return sel


def protocol_comparison():
    st.subheader('Perbandingan ROC-AUC dan PR-AUC berdasarkan rancangan evaluasi')
    df=pd.DataFrame([
        ('Test acak · Bagian 25','Extra Trees vs Blending 60/40',.7982,.8059,.2396,.2533),
        ('Nested CV · Bagian 26','Extra Trees vs Blending adaptif',.7495,.7610,.2226,.2214),
        ('Test kronologis · Bagian 27','Extra Trees vs Extra Trees + indikator missing',.5700,.6612,.0737,.1023),
        ('Outer CV · Bagian 31','Extra Trees vs Blending tetap 60/40',.7495,.7579,.2226,.2252),
    ],columns=['Rancangan','Kandidat yang diuji','ROC-AUC awal','ROC-AUC pengembangan','PR-AUC awal','PR-AUC pengembangan'])
    display_table(df,'Hasil tiap rancangan',
                  'Perbandingan hanya sah dalam baris/rancangan yang sama. Setiap baris mungkin menguji model dan pembagian data berbeda.')
    options=st.selectbox('Pilih rancangan untuk divisualisasikan',df['Rancangan'].tolist(),key='protocol')
    sel=df[df['Rancangan']==options].iloc[0]
    values=pd.DataFrame([
       ('ROC-AUC','Extra Trees awal',sel['ROC-AUC awal']),
       ('ROC-AUC','Pengembangan',sel['ROC-AUC pengembangan']),
       ('PR-AUC','Extra Trees awal',sel['PR-AUC awal']),
       ('PR-AUC','Pengembangan',sel['PR-AUC pengembangan'])
    ],columns=['Metrik','Model','Skor'])
    fig=px.bar(values,x='Metrik',y='Skor',color='Model',barmode='group',text='Skor',
               color_discrete_map={'Extra Trees awal':BLUE,'Pengembangan':TEAL})
    fig.update_traces(texttemplate='%{text:.4f}',textposition='outside')
    chart_layout(fig,350)
    fig.update_yaxes(range=[0,1])
    st.plotly_chart(fig,use_container_width=True)
    st.caption('Pada test kronologis Bagian 27, model baru adalah Extra Trees + indikator missing 100%, bukan Blending 60/40.')


def glossary():
    with st.expander('📘 Panduan membaca metrik — klik untuk membuka'):
        st.markdown('''
**ROC-AUC:** kemampuan model mengurutkan risiko wafer Fail relatif terhadap Pass, tanpa memilih threshold. **PR-AUC:** kualitas hubungan precision–recall untuk kelas Fail yang langka; baseline acak sekitar prevalensi Fail, yaitu 6,64%.

**Recall Fail (sensitivitas):** TP / (TP + FN), yaitu bagian wafer Fail yang berhasil ditemukan. **Recall Pass (spesifisitas):** TN / (TN + FP), yaitu bagian wafer Pass yang dikenali dengan benar.

**Precision Fail:** TP / (TP + FP), yaitu persentase alarm Fail yang benar-benar Fail. **F2-score:** rata-rata harmonik berbobot yang lebih menekankan recall dibanding precision. **MCC:** ukuran korelasi antara label aktual dan prediksi; memperhitungkan semua bagian confusion matrix.

**Threshold:** skor batas untuk mengeluarkan alarm Fail. Menurunkan threshold biasanya menaikkan recall sekaligus alarm palsu. **OOF (out-of-fold):** prediksi pada fold training yang tidak digunakan melatih model tersebut. **Nested CV:** validasi bertingkat yang memisahkan pemilihan konfigurasi dari evaluasi.

**CI 95% selisih:** ukuran ketidakpastian estimasi perbedaan. Jika rentangnya masih mencakup nol, peningkatan belum terbukti signifikan dengan pendekatan interval itu. **FP** = alarm palsu pada Pass; **FN** = Fail yang terlewat.
        ''')


def overview_page():
    header('OVERVIEW / RESEARCH JOURNEY','SECOM — Alur Penelitian dan Pengembangan',
           'Dari model awal Extra Trees sampai evaluasi berpasangan model dan threshold pada Bagian 31.')
    a,b,c,d=st.columns(4)
    a.metric('Total wafer','1.567')
    b.metric('Fitur sensor','590')
    c.metric('Pass','1.463')
    d.metric('Fail','104 (6,64%)')
    note('<b>Temuan utama:</b> ROC-AUC pada test acak meningkat 0,7982 → 0,8059 dengan Blending 60/40. Namun, validasi lanjutan menunjukkan perbaikan kecil dan belum konsisten pada semua rancangan. Jumlah alarm palsu dan produk Fail yang terlewat tetap menjadi perhatian utama.')
    st.markdown('### Perjalanan eksperimen')
    phases=[('Bagian 1–21','Penelitian utama','EDA → 19 algoritma → Extra Trees sebagai model acuan'),
            ('Bagian 22–24','Eksplorasi model','SVM RBF, varian Extra Trees, missingness, konfigurasi'),
            ('Bagian 25','Weighted Blending','60% Extra Trees awal + 40% indikator missing'),
            ('Bagian 26–28','Uji ketahanan','Nested CV, test kronologis, paired bootstrap'),
            ('Bagian 29–30','Keputusan operasional','Threshold OOF, trade-off alarm palsu, biaya dan stabilitas'),
            ('Bagian 31','Validasi akhir','Model + aturan threshold dievaluasi berpasangan pada outer CV')]
    for no,label,desc in phases:
        st.markdown(f'<div class="smallblock"><b>{no} — {label}</b><div>{desc}</div></div>',unsafe_allow_html=True)
    st.markdown('### Ringkasan hasil paling penting')
    c1,c2,c3=st.columns(3)
    c1.metric('ROC-AUC test acak','0,8059','+0,0077 dibanding awal')
    c2.metric('PR-AUC test acak','0,2533','+0,0137 dibanding awal')
    c3.metric('ROC-AUC Blending outer CV','0,7579','+0,0084 vs Extra Trees outer CV')
    st.warning('Test acak, CV, dan test kronologis adalah rancangan berbeda. Jangan disatukan sebagai satu ranking atau menyimpulkan signifikansi dari selisih rata-rata saja.')
    protocol_comparison()
    glossary()


def final_page():
    header('SINTESIS / BAGIAN 1–31','Perbandingan dan Kesimpulan Akhir',
           'Membedakan peningkatan skor, perubahan keputusan Pass/Fail, dan kekuatan bukti validasi.')
    protocol_comparison()
    st.subheader('Dampak threshold terhadap wafer yang benar-benar terdeteksi')
    f=TEST_29.copy()
    show=f[['Skenario','TP','FN','TN','FP','Recall Fail','Recall Pass','Precision Fail','F2','Accuracy','ROC-AUC','PR-AUC']]
    display_table(show,'392 wafer test acak: 26 Fail dan 366 Pass',
                  'Threshold Blending baru 0,1011 dipilih dari training OOF; hasil test tetap bersifat eksploratif.')
    a,b=st.columns(2)
    with a:
        bar=f.melt(id_vars='Skenario',value_vars=['TP','FN'],var_name='Kategori',value_name='Jumlah wafer')
        fig=px.bar(bar,x='Skenario',y='Jumlah wafer',color='Kategori',barmode='stack',text='Jumlah wafer',color_discrete_sequence=[TEAL,ORANGE])
        chart_layout(fig,400)
        st.plotly_chart(fig,use_container_width=True)
    with b:
        bar=f.melt(id_vars='Skenario',value_vars=['TN','FP'],var_name='Kategori',value_name='Jumlah wafer')
        fig=px.bar(bar,x='Skenario',y='Jumlah wafer',color='Kategori',barmode='stack',text='Jumlah wafer',color_discrete_sequence=[BLUE,ORANGE])
        chart_layout(fig,400)
        st.plotly_chart(fig,use_container_width=True)
    st.caption('TP = Fail yang tertangkap; FN = Fail terlewat; TN = Pass benar; FP = alarm palsu.')
    st.subheader('Temuan Bagian 31 dalam konteks operasional')
    f=OUTER_31[OUTER_31['Aturan threshold']=='Target Recall >=81%']
    display_table(f[['Model','ROC-AUC mean','PR-AUC mean','Recall Fail mean','Precision Fail mean','FP per 1000 mean','Biaya/1000 mean (30:1)','Fold target 81%']],
                  'Hasil outer cross-validation, target Recall Fail 81%')
    st.subheader('Apa yang bisa dan belum bisa disimpulkan?')
    a,b=st.columns(2)
    with a:
        note('<b>Yang sudah didukung hasil:</b> Blending 60/40 meningkatkan ROC-AUC dan PR-AUC pada test acak. Pada outer CV Bagian 31, kenaikan ROC-AUC kecil dan jumlah alarm palsu sedikit berkurang pada aturan target recall. Threshold lebih rendah menaikkan deteksi Fail tetapi juga jumlah alarm palsu.')
    with b:
        note('<b>Yang belum terbukti:</b> keunggulan model baru secara konsisten dan signifikan di seluruh evaluasi; kepastian bahwa threshold akan mencapai Recall Fail 81% pada data baru; dan keuntungan operasional tanpa informasi biaya FN/FP sesungguhnya.')
    st.info('Kesimpulan: Weighted Blending 60/40 menunjukkan potensi peningkatan, tetapi belum terbukti lebih unggul secara menyeluruh. Evaluasi pada data independen dan asumsi biaya yang realistis diperlukan sebelum penerapan operasional.')
    glossary()


